-- _alias053: 'repoint' = an 052 alias that follows its target to that row's own successor (so "roti chapati"
-- still serves the row holding the key "chapati roti", 052's reordered-words rule), its note extended with what it
-- serves now; 'insert' = a new alias; 'retire' = an 052 alias whose words become an exact key on a copy row of the
-- very row it served ('chawal', 'phulka'): exact keys win, and the fts resolver reads keys only, never aliases.
-- new_target is the row that serves the phrase afterwards (for 'retire', the key row; logged, never written).
CREATE TEMP TABLE _alias053 (alias text PRIMARY KEY, kind text NOT NULL, expect_target uuid, new_target uuid NOT NULL, note text NOT NULL) ON COMMIT DROP;
